//! Chrome-156 control for the cascade's selectors, end to end through the HTML path
//! (consolidation S3b: turbo-dom-layout matches with turbo-dom's one engine).
//!
//! Reads turbo-dom's `crates/turbo-dom/tests/fixtures/cascade_selectors_chrome156.json`
//! (generated by turbo-dom's `scripts/cascade-selectors-chrome-control.mjs`) and styles
//! each control document through [`style_html_tree`] — the exact styling step of
//! `layout_html` — asserting the computed `order` Chrome reported:
//!
//! - every S3a selector case: with `SEL { order: 1 }` as author CSS, `order` is `1`
//!   exactly where Chrome's `getComputedStyle(el).order` is `1`;
//! - every cascade case (one per S3b quirk class): its sheet's winning `order` per
//!   element.
//!
//! P5b: [`OPEN`] lists the fixture items (selector-case `bug`s, cascade-case `class`es)
//! whose fix has not landed yet; their rows are recorded but not asserted.
//!
//! The HTML path styles the whole document (`<html>`, `<body>` and their content are
//! compared). `<head>` is skipped: Chrome's control appends its sentinel `<style>` to
//! `<head>` (so Chrome's head is never `:empty`), while here the rule is caller CSS and
//! a never-rendered `<head>` has no layout-visible style.
use serde_json::Value;
use turbo_dom::rtdom::tree::NodeType;
use turbo_dom::{Handle, Tree};
use turbo_dom_layout::{parse_html_tree, style_html_tree, HtmlOptions, StyledNode};

/// P5b items not fixed yet (miaskiewicz/turbo-dom#18, #21): skipped until their fixing
/// commit removes them here. miaskiewicz/turbo-dom#58: the fullscreen pseudo-classes.
const OPEN: &[&str] = &["fullscreen"];

fn fixture() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../turbo-dom/tests/fixtures/cascade_selectors_chrome156.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("turbo-dom's Chrome fixture"))
        .unwrap()
}

/// Elements in document order, template content excluded (Chrome walks `children`).
fn elements(tree: &Tree) -> Vec<Handle> {
    fn walk(tree: &Tree, h: Handle, out: &mut Vec<Handle>) {
        for c in tree.children(h) {
            if tree.node_type(c) == NodeType::Element {
                out.push(c);
                walk(tree, c, out);
            }
        }
    }
    let mut out = Vec::new();
    walk(tree, tree.root(), &mut out);
    out
}

/// `(source handle, computed order)` of every styled element.
fn orders(nodes: &[StyledNode], out: &mut Vec<(Handle, String)>) {
    for node in nodes {
        if let StyledNode::Element(e) = node {
            let order = e.style.get("order").unwrap_or("0").to_string();
            out.push((e.source.expect("Tree input"), order));
            orders(&e.children, out);
        }
    }
}

/// Style `html` with `css` appended as author CSS and compare each styled element's
/// `order` with Chrome's per-element list.
fn check(html: &str, css: &str, want: &[String], what: &str, failures: &mut Vec<String>) -> usize {
    let tree = parse_html_tree(html);
    let els = elements(&tree);
    let styled = style_html_tree(&tree, css, 1280.0, &HtmlOptions::default());
    let mut got = Vec::new();
    orders(&styled, &mut got);
    for (h, order) in &got {
        if tree.local_name(*h) == Some("head") {
            continue;
        }
        let i = els
            .iter()
            .position(|e| e == h)
            .expect("styled elements are parsed elements");
        if *order != want[i] {
            failures.push(format!(
                "{what}: el#{i} <{}> order {order}, Chrome {}",
                tree.local_name(*h).unwrap_or(""),
                want[i]
            ));
        }
    }
    got.len()
}

#[test]
fn html_path_cascade_matches_chrome156() {
    let fixture = fixture();
    assert!(fixture["chrome"].as_str().unwrap().starts_with("156."));
    let mut failures = Vec::new();
    let mut compared = 0;
    for case in fixture["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        if OPEN.contains(&case["bug"].as_str().unwrap()) {
            continue;
        }
        let html = case["html"].as_str().unwrap();
        for row in case["selectors"].as_array().unwrap() {
            let sel = row["selector"].as_str().unwrap();
            let want: Vec<String> = row["winner"]
                .as_str()
                .unwrap()
                .chars()
                .map(String::from)
                .collect();
            let css = format!("{sel} {{ order: 1 }}");
            compared += check(html, &css, &want, &format!("{id} `{sel}`"), &mut failures);
        }
    }
    let cascade = fixture["cascade_cases"].as_array().unwrap();
    for case in cascade {
        let id = case["id"].as_str().unwrap();
        if OPEN.contains(&case["class"].as_str().unwrap()) {
            continue;
        }
        let want: Vec<String> = case["winners"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect();
        compared += check(
            case["html"].as_str().unwrap(),
            case["css"].as_str().unwrap(),
            &want,
            id,
            &mut failures,
        );
    }
    assert!(
        compared > 1000,
        "fixture shrank: {compared} element comparisons"
    );
    assert!(
        failures.is_empty(),
        "{} disagreements with Chrome 156:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
